document.addEventListener("DOMContentLoaded",()=>{if("undefined"==typeof gsap)return;if(window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;document.querySelectorAll(".desktop-nav .nav-link").forEach(e=>{e.addEventListener("mouseenter",()=>{gsap.to(e,{scale:1.04,duration:.2,ease:"power3.out"})}),e.addEventListener("mouseleave",()=>{gsap.to(e,{scale:1,duration:.2,ease:"power3.out"})})});const e=document.querySelector(".logo");e&&(e.addEventListener("mouseenter",()=>{gsap.to(e.querySelector(".logo-icon"),{rotation:8,scale:1.08,duration:.3,ease:"power3.out"})}),e.addEventListener("mouseleave",()=>{gsap.to(e.querySelector(".logo-icon"),{rotation:0,scale:1,duration:.3,ease:"power3.out"})})),document.querySelectorAll(".btn").forEach(e=>{e.addEventListener("mousedown",()=>{e.classList.contains("magnetic")||gsap.to(e,{scale:.96,duration:.08,ease:"power2.in"})}),e.addEventListener("mouseup",()=>{e.classList.contains("magnetic")||gsap.to(e,{scale:1,duration:.2,ease:"power3.out"})}),e.addEventListener("mouseleave",()=>{e.classList.contains("magnetic")||gsap.to(e,{scale:1,duration:.15,ease:"power3.out"})})}),document.querySelectorAll(".filter-btn").forEach(e=>{e.addEventListener("click",()=>{gsap.fromTo(e,{scale:.92},{scale:1,duration:.3,ease:"power3.out"})})}),document.querySelectorAll(".social-link").forEach(e=>{e.addEventListener("mouseenter",()=>{gsap.to(e,{y:-3,scale:1.1,duration:.2,ease:"power3.out"})}),e.addEventListener("mouseleave",()=>{gsap.to(e,{y:0,scale:1,duration:.2,ease:"power3.out"})})}),document.querySelectorAll(".product-card:not([data-product])").forEach(e=>{e.addEventListener("mouseenter",()=>{gsap.to(e,{boxShadow:"0 0 24px rgba(0, 212, 170, 0.15)",duration:.3,ease:"power3.out"})}),e.addEventListener("mouseleave",()=>{gsap.to(e,{boxShadow:"0 0 0 rgba(0, 212, 170, 0)",duration:.4,ease:"power3.out"})})}),document.querySelectorAll(".scroll-btn").forEach(e=>{e.addEventListener("mouseenter",()=>{gsap.to(e,{scale:1.08,duration:.2,ease:"power3.out"})}),e.addEventListener("mouseleave",()=>{gsap.to(e,{scale:1,duration:.2,ease:"power3.out"})})})});